diff --git a/docs/progress/dashboard/dashboard.css b/docs/progress/dashboard/dashboard.css
new file mode 100644
index 0000000..3385d5f
--- /dev/null
+++ b/docs/progress/dashboard/dashboard.css
@@ -0,0 +1,181 @@
+:root {
+  color-scheme: dark;
+  --bg: #0f1114;
+  --surface: #171a1f;
+  --surface-2: #1d2127;
+  --border: #343942;
+  --text: #f3f4f6;
+  --muted: #a7adb7;
+  --track: #2a2f36;
+  --bar: #d9dde3;
+  --pass: #8fd3a8;
+  --warn: #e3c778;
+  --fail: #ef9a9a;
+  --info: #b9c2d0;
+  --radius: 16px;
+}
+
+* { box-sizing: border-box; }
+
+body {
+  margin: 0;
+  min-height: 100vh;
+  background: var(--bg);
+  color: var(--text);
+  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+  line-height: 1.5;
+}
+
+body::before {
+  content: "";
+  position: fixed;
+  inset: 0;
+  pointer-events: none;
+  background: radial-gradient(circle at 15% 0%, rgba(255,255,255,.055), transparent 34%);
+}
+
+.page-header,
+main,
+footer {
+  width: min(1180px, calc(100% - 32px));
+  margin-inline: auto;
+}
+
+.page-header {
+  display: flex;
+  justify-content: space-between;
+  gap: 24px;
+  align-items: flex-start;
+  padding: 46px 0 30px;
+  border-bottom: 1px solid var(--border);
+}
+
+h1, h2, h3, p { margin-top: 0; }
+h1 { margin-bottom: 10px; font-size: clamp(2rem, 5vw, 3.5rem); line-height: 1.02; letter-spacing: -0.04em; }
+h2 { margin-bottom: 0; font-size: clamp(1.25rem, 2.2vw, 1.7rem); letter-spacing: -0.02em; }
+h3 { margin-bottom: 8px; font-size: 1rem; }
+code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
+
+.eyebrow {
+  margin-bottom: 8px;
+  color: var(--muted);
+  font-size: .76rem;
+  font-weight: 700;
+  letter-spacing: .11em;
+  text-transform: uppercase;
+}
+
+.lede,
+.muted,
+.footnote { color: var(--muted); }
+.lede { max-width: 760px; margin-bottom: 0; }
+.footnote { margin: 16px 0 0; font-size: .84rem; }
+
+.status-pill {
+  flex: 0 0 auto;
+  padding: 9px 13px;
+  border: 1px solid var(--border);
+  border-radius: 999px;
+  background: var(--surface);
+  font-size: .86rem;
+  font-weight: 700;
+}
+
+main { padding: 8px 0 56px; }
+section { margin-top: 44px; }
+
+.section-heading {
+  display: flex;
+  justify-content: space-between;
+  align-items: end;
+  gap: 20px;
+  margin-bottom: 18px;
+}
+.section-heading.compact { align-items: center; }
+
+.summary-grid {
+  display: grid;
+  grid-template-columns: repeat(6, minmax(0, 1fr));
+  gap: 12px;
+}
+
+.summary-card,
+.panel,
+.milestone-card {
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  background: linear-gradient(180deg, var(--surface-2), var(--surface));
+}
+
+.summary-card { padding: 18px; min-height: 116px; }
+.summary-card .value { display: block; margin-top: 12px; font-size: 1.65rem; font-weight: 800; letter-spacing: -.03em; }
+.summary-card .label { color: var(--muted); font-size: .82rem; }
+
+.overall-progress { margin-top: 14px; padding: 18px; border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); }
+.progress-meta { display: flex; justify-content: space-between; gap: 16px; margin-bottom: 10px; font-size: .88rem; }
+.progress-track { height: 9px; overflow: hidden; border-radius: 999px; background: var(--track); }
+.progress-bar { width: 0; height: 100%; border-radius: inherit; background: var(--bar); transition: width .35s ease; }
+
+.milestone-list { display: grid; gap: 12px; }
+.milestone-card { padding: 18px; }
+.milestone-top { display: flex; justify-content: space-between; align-items: center; gap: 16px; }
+.milestone-title { display: flex; align-items: center; gap: 10px; }
+.badge { padding: 4px 8px; border: 1px solid var(--border); border-radius: 999px; color: var(--muted); font-size: .72rem; font-weight: 700; }
+.badge.pass { color: var(--pass); }
+.badge.progress { color: var(--warn); }
+.milestone-meta { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; margin-top: 14px; color: var(--muted); font-size: .8rem; }
+.milestone-meta strong { display: block; margin-top: 3px; color: var(--text); font-size: .92rem; }
+
+.two-column { display: grid; grid-template-columns: 1.1fr .9fr; gap: 16px; }
+.panel { padding: 20px; min-width: 0; }
+.chart { min-height: 280px; overflow-x: auto; }
+.chart svg { display: block; width: 100%; min-width: 520px; height: 280px; }
+.chart text { fill: var(--muted); font-size: 11px; }
+.chart .axis { stroke: var(--border); stroke-width: 1; }
+.chart .line { fill: none; stroke: var(--bar); stroke-width: 2.5; }
+.chart .point { fill: var(--text); stroke: var(--bg); stroke-width: 2; }
+
+.timing-list { display: grid; gap: 10px; }
+.timing-row { display: flex; justify-content: space-between; gap: 16px; padding: 12px 0; border-bottom: 1px solid var(--border); }
+.timing-row:last-child { border-bottom: 0; }
+.timing-row span { color: var(--muted); }
+
+.table-wrap { overflow-x: auto; border: 1px solid var(--border); border-radius: var(--radius); }
+table { width: 100%; border-collapse: collapse; min-width: 780px; background: var(--surface); }
+th, td { padding: 13px 14px; text-align: left; vertical-align: top; border-bottom: 1px solid var(--border); font-size: .86rem; }
+th { color: var(--muted); font-size: .74rem; text-transform: uppercase; letter-spacing: .08em; }
+tr:last-child td { border-bottom: 0; }
+
+.stack-list { display: grid; gap: 10px; }
+.stack-item { padding: 12px 0; border-bottom: 1px solid var(--border); }
+.stack-item:last-child { border-bottom: 0; }
+.stack-item code { overflow-wrap: anywhere; }
+.stack-item .sub { margin-top: 4px; color: var(--muted); font-size: .78rem; }
+
+.timeline { display: grid; gap: 10px; }
+.timeline-item { display: grid; grid-template-columns: 190px 130px 1fr; gap: 14px; padding: 14px 16px; border-left: 2px solid var(--border); background: rgba(255,255,255,.015); }
+.timeline-item.failed { border-left-color: var(--fail); }
+.timeline-item.passed { border-left-color: var(--pass); }
+.timeline-time, .timeline-type { color: var(--muted); font-size: .78rem; }
+.timeline-summary { font-size: .9rem; }
+.timeline-summary small { display: block; margin-top: 5px; color: var(--muted); }
+
+footer { display: flex; justify-content: space-between; gap: 20px; padding: 22px 0 40px; border-top: 1px solid var(--border); color: var(--muted); font-size: .78rem; }
+footer p { margin: 0; }
+
+.load-error { position: fixed; right: 18px; bottom: 18px; max-width: 560px; padding: 16px; border: 1px solid var(--fail); border-radius: 12px; background: #241719; color: var(--text); box-shadow: 0 16px 40px rgba(0,0,0,.35); }
+.load-error span { display: block; margin-top: 6px; color: var(--muted); }
+
+@media (max-width: 960px) {
+  .summary-grid { grid-template-columns: repeat(3, 1fr); }
+  .two-column { grid-template-columns: 1fr; }
+  .milestone-meta { grid-template-columns: repeat(3, 1fr); }
+}
+
+@media (max-width: 640px) {
+  .page-header { flex-direction: column; padding-top: 30px; }
+  .summary-grid { grid-template-columns: repeat(2, 1fr); }
+  .milestone-top, .section-heading, footer { align-items: flex-start; flex-direction: column; }
+  .milestone-meta { grid-template-columns: repeat(2, 1fr); }
+  .timeline-item { grid-template-columns: 1fr; gap: 4px; }
+}

diff --git a/docs/progress/dashboard/dashboard.js b/docs/progress/dashboard/dashboard.js
new file mode 100644
index 0000000..2e4fea1
--- /dev/null
+++ b/docs/progress/dashboard/dashboard.js
@@ -0,0 +1,199 @@
+(() => {
+  "use strict";
+
+  const byId = (id) => document.getElementById(id);
+  const escapeHtml = (value) => String(value ?? "")
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#039;");
+
+  const formatTime = (value) => {
+    if (!value) return "time not preserved";
+    const date = new Date(value);
+    return Number.isNaN(date.getTime()) ? value : date.toLocaleString();
+  };
+
+  const badgeClass = (status) => status === "QUALIFIED" ? "pass" : "progress";
+
+  function renderSummary(data) {
+    const summary = data.summary;
+    byId("current-milestone").textContent = `Current · ${summary.current_milestone}`;
+    const cards = [
+      ["Tracked milestones", summary.tracked_milestones],
+      ["Qualified", summary.qualified_milestones],
+      ["Passed events", summary.passed_events],
+      ["Failed events", summary.failed_events],
+      ["Corrections", summary.corrections],
+      ["Commits", summary.commits],
+    ];
+    byId("summary-grid").innerHTML = cards.map(([label, value]) => `
+      <article class="summary-card">
+        <span class="label">${escapeHtml(label)}</span>
+        <span class="value">${escapeHtml(value)}</span>
+      </article>
+    `).join("");
+
+    const completion = Number(summary.tracked_completion_percent || 0);
+    byId("overall-progress-label").textContent = `${completion.toFixed(1)}%`;
+    byId("overall-progress-bar").style.width = `${Math.max(0, Math.min(100, completion))}%`;
+    byId("ledger-head").textContent = `${data.ledger.head_event_id} · ${data.ledger.event_count} events`;
+  }
+
+  function renderMilestones(data) {
+    byId("milestone-list").innerHTML = data.milestones.map((item) => `
+      <article class="milestone-card">
+        <div class="milestone-top">
+          <div class="milestone-title">
+            <h3><code>${escapeHtml(item.milestone)}</code></h3>
+            <span class="badge ${badgeClass(item.status)}">${escapeHtml(item.status)}</span>
+          </div>
+          <strong>${escapeHtml(item.progress_percent)}%</strong>
+        </div>
+        <div class="progress-track"><div class="progress-bar" style="width:${Math.max(0, Math.min(100, item.progress_percent))}%"></div></div>
+        <div class="milestone-meta">
+          <span>Difficulty<strong>${escapeHtml(item.observed_difficulty)}/5</strong></span>
+          <span>Failures<strong>${escapeHtml(item.failure_count)}</strong></span>
+          <span>Corrections<strong>${escapeHtml(item.correction_count)}</strong></span>
+          <span>Elapsed<strong>${escapeHtml(item.elapsed_label)}</strong></span>
+          <span>Command runtime<strong>${escapeHtml(item.recorded_command_runtime_label)}</strong></span>
+        </div>
+      </article>
+    `).join("");
+  }
+
+  function renderDifficulty(data) {
+    const items = data.milestones;
+    const width = Math.max(520, items.length * 95 + 80);
+    const height = 280;
+    const left = 38;
+    const top = 18;
+    const bottom = 48;
+    const chartHeight = height - top - bottom;
+    const usableWidth = width - left - 24;
+    const step = items.length > 1 ? usableWidth / (items.length - 1) : usableWidth;
+    const y = (score) => top + chartHeight - ((Number(score) - 1) / 4) * chartHeight;
+    const points = items.map((item, index) => ({
+      x: items.length > 1 ? left + step * index : left + usableWidth / 2,
+      y: y(item.observed_difficulty),
+      item,
+    }));
+    const path = points.map((point, index) => `${index === 0 ? "M" : "L"}${point.x},${point.y}`).join(" ");
+    const grid = [1, 2, 3, 4, 5].map((score) => {
+      const yy = y(score);
+      return `<line class="axis" x1="${left}" y1="${yy}" x2="${width - 24}" y2="${yy}"></line><text x="10" y="${yy + 4}">${score}</text>`;
+    }).join("");
+    const marks = points.map((point) => `
+      <circle class="point" cx="${point.x}" cy="${point.y}" r="5"></circle>
+      <text x="${point.x}" y="${height - 18}" text-anchor="middle">${escapeHtml(point.item.milestone.replace("CWTV.", ""))}</text>
+      <text x="${point.x}" y="${point.y - 10}" text-anchor="middle">${escapeHtml(point.item.observed_difficulty)}</text>
+    `).join("");
+    byId("difficulty-chart").innerHTML = `
+      <svg viewBox="0 0 ${width} ${height}" aria-hidden="true">
+        ${grid}
+        <path class="line" d="${path}"></path>
+        ${marks}
+      </svg>
+    `;
+  }
+
+  function renderTiming(data) {
+    const current = data.milestones.find((item) => item.milestone === data.summary.current_milestone) || data.milestones.at(-1);
+    if (!current) {
+      byId("timing-list").textContent = "No timing data recorded.";
+      return;
+    }
+    const rows = [
+      ["Current milestone", current.milestone],
+      ["Elapsed", current.elapsed_label],
+      ["Recorded command runtime", current.recorded_command_runtime_label],
+      ["Active session time", current.active_session_label],
+      ["Paused time", current.paused_label],
+      ["Explicit breaks", current.session_data_present ? current.break_count : "not preserved"],
+    ];
+    byId("timing-list").innerHTML = rows.map(([label, value]) => `
+      <div class="timing-row"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>
+    `).join("");
+  }
+
+  function renderFailures(data) {
+    const tbody = byId("failures-body");
+    if (!data.failures.length) {
+      tbody.innerHTML = `<tr><td colspan="5">No failed events recorded.</td></tr>`;
+      return;
+    }
+    tbody.innerHTML = data.failures.map((event) => `
+      <tr>
+        <td><code>${escapeHtml(event.milestone)}</code></td>
+        <td>${escapeHtml(formatTime(event.occurred_at))}</td>
+        <td>${escapeHtml(event.component || "—")}</td>
+        <td>${escapeHtml(event.summary)}</td>
+        <td>${escapeHtml(event.correction || "—")}</td>
+      </tr>
+    `).join("");
+  }
+
+  function renderArtifacts(data) {
+    const seen = new Set();
+    const unique = data.artifacts.filter((event) => {
+      const key = `${event.artifact?.name || ""}|${event.artifact?.sha256 || ""}|${event.event_type}`;
+      if (seen.has(key)) return false;
+      seen.add(key);
+      return true;
+    });
+    byId("artifact-list").innerHTML = unique.length ? unique.map((event) => `
+      <div class="stack-item">
+        <strong><code>${escapeHtml(event.artifact.name)}</code></strong>
+        <div class="sub">${escapeHtml(event.event_type)} · ${escapeHtml(formatTime(event.occurred_at))}</div>
+        <div class="sub">${event.artifact.sha256 ? `SHA-256 ${escapeHtml(event.artifact.sha256)}` : "SHA-256 recorded after finalized archive verification"}</div>
+      </div>
+    `).join("") : `<div class="stack-item">No artifact events recorded.</div>`;
+  }
+
+  function renderCommits(data) {
+    byId("commit-list").innerHTML = data.commits.length ? data.commits.map((event) => `
+      <div class="stack-item">
+        <strong><code>${escapeHtml(event.commit)}</code></strong>
+        <div class="sub">${escapeHtml(event.summary)}</div>
+        <div class="sub">${escapeHtml(formatTime(event.occurred_at))}</div>
+      </div>
+    `).join("") : `<div class="stack-item">No commit events recorded.</div>`;
+  }
+
+  function renderTimeline(data) {
+    byId("timeline").innerHTML = data.events.map((event) => {
+      const klass = event.result === "FAILED" ? "failed" : (event.result === "PASS" || event.result === "QUALIFIED" ? "passed" : "");
+      const evidence = event.evidence?.length ? `<small>${escapeHtml(event.evidence.join(" · "))}</small>` : "";
+      const duration = event.duration_seconds != null ? `<small>Duration: ${escapeHtml(event.duration_seconds)}s</small>` : "";
+      return `
+        <article class="timeline-item ${klass}">
+          <div class="timeline-time">${escapeHtml(formatTime(event.occurred_at))}</div>
+          <div class="timeline-type"><code>${escapeHtml(event.event_type)}</code></div>
+          <div class="timeline-summary"><strong>${escapeHtml(event.milestone)}</strong> · ${escapeHtml(event.summary)}${duration}${evidence}</div>
+        </article>
+      `;
+    }).join("");
+  }
+
+  fetch("./progress-data.json", { cache: "no-store" })
+    .then((response) => {
+      if (!response.ok) throw new Error(`HTTP ${response.status}`);
+      return response.json();
+    })
+    .then((data) => {
+      renderSummary(data);
+      renderMilestones(data);
+      renderDifficulty(data);
+      renderTiming(data);
+      renderFailures(data);
+      renderArtifacts(data);
+      renderCommits(data);
+      renderTimeline(data);
+    })
+    .catch((error) => {
+      console.error(error);
+      byId("load-error").hidden = false;
+      byId("current-milestone").textContent = "Data unavailable";
+    });
+})();

